// src/services/cv/poseSource.ts  (PoseSource = 'mock' | 'mediapipe' from contracts.ts)
export type PoseSourceError = 'permission_denied' | 'camera_error' | 'stalled';
export interface PoseSourceStats { readonly delivered: number; readonly dropped: number }
export interface PoseSourceProvider {
  readonly kind: PoseSource;
  start(onFrame: (frame: PoseFrame) => void, onError: (error: PoseSourceError) => void): void;
  stop(): void;
  ingest(raw: RawPoseResult): void;            // mediapipe: map + forward; mock: no-op
  reportNativeError(error: 'permission_denied' | 'camera_error'): void;
  stats(): PoseSourceStats;
}
export const POSE_STALL_MS = 1500;

// src/services/cv/poseFrame.ts
export interface RawPoseResult {
  readonly landmarks: ReadonlyArray<{ x: number; y: number; z: number; visibility?: number }>; // normalized [0,1], MediaPipe order
  readonly timestampMs: number;
  readonly imageWidth: number;
  readonly imageHeight: number;
}
export function toPoseFrame(raw: RawPoseResult, frameIndex: number): PoseFrame | null; // source 'mediapipe'

// src/services/cv/poseSource.ts
export interface PoseClock { setInterval(fn: () => void, ms: number): unknown; clearInterval(handle: unknown): void; now(): number }
export type PoseSourceUnavailableReason = 'consent_missing' | 'parent_locked' | 'native_unavailable';
export function createMockPoseSource(opts: MockPoseOptions, clock?: PoseClock): PoseSourceProvider;   // wraps createMockPoseStream, interval 1000/fps, frames passed through sanitizePoseFrame
export function createMediapipePoseSource(clock?: PoseClock): PoseSourceProvider;                    // pure hub fed by ingest(); stall watchdog on clock
export function selectPoseSource(opts: {
  simulate: boolean; consentGranted: boolean; liveAllowed: boolean; nativeAvailable: boolean;
  scenario: MockScenario; seed?: number; clock?: PoseClock;
}): { ok: true; provider: PoseSourceProvider } | { ok: false; reason: PoseSourceUnavailableReason };

